"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[1129],{31129:e=>{e.exports=JSON.parse('{"meta":{"title":"Support & FAQ - iMuslim Life","description":"Find answers to frequently asked questions about iMuslim Life prayer times, features, and get support."},"heading":"Frequently Asked Questions & Support","items":[{"q":"How are the prayer times calculated?","a":"We use highly accurate calculation methods based on astronomical formulas. You can choose from various calculation methods in the settings to match your local mosque or preference."},{"q":"Is my location data stored?","a":"We prioritize your privacy. Location data is only used temporarily to fetch prayer times and is not stored on our servers unless you explicitly save a location."},{"q":"Can I use this app offline?","a":"Basic features like the Quran reader might work offline if previously loaded. However, fetching prayer times for new locations or dates requires an internet connection."},{"q":"How can I report an issue or suggest a feature?","a":"We\'d love to hear from you! Please use the contact button below or reach out to us via our support channels mentioned in the contact section."},{"q":"Is the app completely free?","a":"Yes, iMuslim Life is 100% free and ad-free. Our goal is to provide essential Islamic tools accessible to everyone."}],"contact":{"title":"Need More Help?","text":"If you didn\'t find your answer here, feel free to reach out to our support team.","button":"Contact Support"}}')}}]);